#!/usr/bin/env node
/**
 * Dependency-free token compiler.
 *
 * It reads DTCG-shaped JSON token files, merges a core + semantic layer with
 * each theme, resolves `{alias.paths}`, and emits web CSS and TypeScript.
 */
import {fileURLToPath} from 'node:url';
import {dirname, join, relative, resolve} from 'node:path';
import {copyFile, mkdir, readFile, writeFile} from 'node:fs/promises';

const scriptDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(scriptDir, '..');
const generatedNotice =
  '// Generated by scripts/build-tokens.mjs. Do not edit.\n';
const generatedCssNotice =
  '/* Generated by scripts/build-tokens.mjs. Do not edit. */\n';

const deepMerge = (base, override) => {
  if (Array.isArray(base) || Array.isArray(override)) {
    return override ?? base;
  }
  if (
    !base ||
    typeof base !== 'object' ||
    !override ||
    typeof override !== 'object'
  ) {
    return override ?? base;
  }
  const result = {...base};
  for (const [key, value] of Object.entries(override)) {
    result[key] = deepMerge(result[key], value);
  }
  return result;
};

const flattenTokens = (node, path = [], inheritedType, result = new Map()) => {
  if (!node || typeof node !== 'object') {
    return result;
  }
  const type = node.$type ?? inheritedType;
  if (Object.hasOwn(node, '$value')) {
    result.set(path.join('.'), {value: node.$value, type});
    return result;
  }
  for (const [key, value] of Object.entries(node)) {
    if (!key.startsWith('$')) {
      flattenTokens(value, [...path, key], type, result);
    }
  }
  return result;
};

const resolveValues = tokens => {
  const cache = new Map();
  const resolvePath = (path, trail = []) => {
    if (cache.has(path)) {
      return cache.get(path);
    }
    if (trail.includes(path)) {
      throw new Error(`Circular token alias: ${[...trail, path].join(' -> ')}`);
    }
    const token = tokens.get(path);
    if (!token) {
      throw new Error(`Unknown token alias: ${path}`);
    }
    const raw = token.value;
    const value =
      typeof raw === 'string'
        ? raw.replace(
            /\{([^}]+)\}/g,
            (_, alias) => resolvePath(alias.trim(), [...trail, path]).value,
          )
        : raw;
    const resolved = {...token, value};
    cache.set(path, resolved);
    return resolved;
  };
  return new Map([...tokens.keys()].map(path => [path, resolvePath(path)]));
};

const cssName = path =>
  `--rc-${path.replaceAll('.', '-').replace(/[A-Z]/g, char => `-${char.toLowerCase()}`)}`;
const sorted = tokens =>
  [...tokens.entries()].sort(([a], [b]) => a.localeCompare(b));
const cssDeclarations = tokens =>
  sorted(tokens)
    .map(([path, token]) => `  ${cssName(path)}: ${token.value};`)
    .join('\n');

const renderCss = (core, themes) =>
  `${generatedCssNotice}@font-face { font-family: "GnuMICR"; src: url("../assets/GnuMICR.otf") format("opentype"), url("../assets/GnuMICR.ttf") format("truetype"); font-weight: 400; font-style: normal; font-display: swap; }\n\n:root {\n${cssDeclarations(core)}\n}\n\n:root, [data-theme="light"] {\n${cssDeclarations(themes.light)}\n}\n\n[data-theme="dark"] {\n${cssDeclarations(themes.dark)}\n}\n`;

const renderTypeScript = (core, themes) => {
  const object = tokens =>
    Object.fromEntries(
      sorted(tokens).map(([path, token]) => [path, token.value]),
    );
  return `${generatedNotice}export const coreTokens = ${JSON.stringify(object(core), null, 2)} as const;\n\nexport const themes = ${JSON.stringify(Object.fromEntries(Object.entries(themes).map(([name, tokens]) => [name, object(tokens)])), null, 2)} as const;\n\nexport type ThemeName = keyof typeof themes;\nexport type TokenPath = keyof typeof coreTokens | keyof typeof themes.light;\n\nexport const cssVariable = (path: TokenPath): string => \`--rc-\${path.replaceAll('.', '-')}\`;\n`;
};

const loadJson = async path => JSON.parse(await readFile(path, 'utf8'));

export async function compileTokens(rootDir = projectRoot) {
  const tokenDir = join(rootDir, 'tokens');
  const [core, semantic, light, dark] = await Promise.all([
    loadJson(join(tokenDir, 'core.tokens.json')),
    loadJson(join(tokenDir, 'semantic.tokens.json')),
    loadJson(join(tokenDir, 'themes', 'light.tokens.json')),
    loadJson(join(tokenDir, 'themes', 'dark.tokens.json')),
  ]);
  const shared = deepMerge(core, semantic);
  const coreResolved = resolveValues(flattenTokens(core));
  const themeResolved = Object.fromEntries(
    Object.entries({light, dark}).map(([name, theme]) => [
      name,
      resolveValues(flattenTokens(deepMerge(shared, theme))),
    ]),
  );
  return {
    'css/tokens.css': renderCss(coreResolved, themeResolved),
    'types/tokens.ts': renderTypeScript(coreResolved, themeResolved),
  };
}

export async function writeTokenArtifacts(
  rootDir = projectRoot,
  outputDir = join(rootDir, 'src', 'tokens'),
) {
  const artifacts = await compileTokens(rootDir);
  await Promise.all(
    Object.entries(artifacts).map(async ([file, contents]) => {
      const target = join(outputDir, file);
      await mkdir(dirname(target), {recursive: true});
      await writeFile(target, contents);
    }),
  );
  await Promise.all(
    [
      ['noise.svg', 'noise.svg'],
      ['fonts/GnuMICR.otf', 'GnuMICR.otf'],
      ['fonts/GnuMICR.ttf', 'GnuMICR.ttf'],
    ].map(async ([source, target]) => {
      const destination = join(outputDir, 'assets', target);
      await mkdir(dirname(destination), {recursive: true});
      await copyFile(join(rootDir, 'assets', 'brand', source), destination);
    }),
  );
  return artifacts;
}

const isMain =
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const outIndex = process.argv.indexOf('--out');
  const outputDir =
    outIndex === -1
      ? join(projectRoot, 'src', 'tokens')
      : resolve(process.argv[outIndex + 1]);
  await writeTokenArtifacts(projectRoot, outputDir);
  console.log(
    `Built Reclaim token artifacts in ${relative(projectRoot, outputDir) || '.'}`,
  );
}
